-- Datos de referencia: aeropuertos grandes con vuelos comerciales (1151 filas).
--
-- Origen: OurAirports (https://ourairports.com/data/), datos de DOMINIO
-- PÚBLICO. Filtro: type = large_airport, scheduled_service = yes y código
-- IATA de 3 letras. Para regenerarlo, ver services/geo-engine/README.md.
--
-- ST_MakePoint recibe (longitud, latitud): X primero, como en WKB.
-- ON CONFLICT DO NOTHING hace la carga repetible sin duplicar filas.
ON CONFLICT (iata_code) DO NOTHING;
